SELECT (SELECT PARAMETER_VALUE FROM AZ_PARAMETERS WHERE PARAMETER_NAME = 'OLE_SRC_FACTOOIOENTRY_ContainerName' AND PIPELINE_NAME = 'FactData_Correction_OOO' AND DATAFLOW_NAME = 'DFT_FACTDATA_CRRECTION') AS OLE_SRC_FACTOOIOENTRY_ContainerName,
(SELECT PARAMETER_VALUE FROM AZ_PARAMETERS WHERE PARAMETER_NAME = 'OLE_SRC_FACTOOIOENTRY_FileName' AND PIPELINE_NAME = 'FactData_Correction_OOO' AND DATAFLOW_NAME = 'DFT_FACTDATA_CRRECTION') AS OLE_SRC_FACTOOIOENTRY_FileName,
(SELECT PARAMETER_VALUE FROM AZ_PARAMETERS WHERE PARAMETER_NAME = 'OLE_SRC_FACTOOIOENTRY_FilePath' AND PIPELINE_NAME = 'FactData_Correction_OOO' AND DATAFLOW_NAME = 'DFT_FACTDATA_CRRECTION') AS OLE_SRC_FACTOOIOENTRY_FilePath;
